def table(rows,heads):return '<div class="tableWrap"><table><thead><tr>'+''.join('<th>'+v+'</th>' for v in heads)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(('<th scope="row">' if i==0 else '<td>')+v+('</th>' if i==0 else '</td>') for i,v in enumerate(row))+'</tr>' for row in rows)+'</tbody></table></div>'
h=(A/'stroke.html').read_text().replace('Инсульты','Сосудистые мальформации').replace('1.99','2.00').replace('stroke.js','vascular-malformations.js').replace('Сосудистые изменения · взрослые','Мальформации и венозные аномалии').replace('Ишемия · кровь · давность · сосуды · описание','Кавернома · телеангиэктазия · ВАР / DVA · АВМ · фистула')
buttons=''.join('<button data-feature="'+x['id']+'" aria-pressed="'+str(i==0).lower()+'">'+label+'</button>' for i,(x,label) in enumerate(zip(data['features'],['Кавернома','Телеангиэктазия','ВАР / DVA','DVA + кавернома','АВМ','Фистула'])))
